-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'INTRODUCAO TIC' and a.numero = 4
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 4 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade de Sala 16/10 — Discursivas', 'PENDENTE', v_aula, 'Atividade — Atividade de Sala 16/10 — Discursivas (20 questões discursivas)',
      '/MATERIAIS/ASSISTENTE-DE-OPERACOES-LOGISTICAS/INTRODUCAO-TIC/ATIVIDADES/ATIVIDADE-SALA-AULA-16-10-2026-DISCURSIVA.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explicação do e-mail como documento oficial e auditável, com exemplo de uso.', 0.5, 'O e-mail corporativo funciona como documento oficial auditável: fica registrado com data, hora, remetente e destinatário, serve de prova das decisões e responsabilidades e tem validade jurídica. Aplicativos de mensagens instantâneas são informais e as conversas se perdem. Ex.: o pedido de compra enviado por e-mail mostra quem pediu, o quê e quando, se houver dúvida na entrega.', 'Nota cheia: explica o registro oficial/auditável (prova, responsabilidade) e dá um exemplo ou compara com o aplicativo. Metade: só diz que é "mais formal" ou "fica registrado", sem explicar. Zero: justificativa errada (ex.: "é mais rápido") ou em branco.'),
      (v_atividade, 2, 1, 'Assunto no padrão da fórmula e explicação do problema do assunto vago.', 0.5, 'Ex.: "[Almoxarifado] Inventário mensal de outubro – Entrega 20/10". O assunto "Urgente!!!" é vago: não diz do que se trata nem o prazo, então o destinatário não consegue priorizar, e o excesso de exclamações passa falta de profissionalismo.', 'Nota cheia: assunto com setor/projeto, assunto e ação/prazo, e explicação de que o assunto vago não informa nem ajuda a priorizar. Metade: assunto adequado sem explicação, ou explicação sem assunto no padrão. Zero: assunto vago ou em branco.'),
      (v_atividade, 3, 1, 'Campo correto e justificativa ligada à privacidade e à LGPD.', 0.5, 'No CCO (cópia oculta). Assim nenhum fornecedor vê o endereço dos outros, o que protege a privacidade dos contatos e evita vazamento de dados. Enviar e-mail em massa com os endereços visíveis (no Para ou no CC) expõe dados pessoais e viola a LGPD.', 'Nota cheia: CCO com justificativa de privacidade e citação da LGPD. Metade: CCO com justificativa sem a LGPD, ou só "CCO" com LGPD sem explicar. Zero: Para ou CC, ou em branco.'),
      (v_atividade, 4, 1, 'Forma de envio adequada para arquivos grandes e aviso no corpo do e-mail.', 0.5, 'Arquivos acima de 20 MB podem ser bloqueados pelos filtros do e-mail; por isso o relatório deve ser salvo na nuvem (Google Drive, OneDrive ou Dropbox) e enviado o link de acesso, com a permissão adequada. No corpo do e-mail é preciso avisar que o relatório está no link, dizer o que ele contém e pedir a confirmação do recebimento.', 'Nota cheia: envio por link de armazenamento em nuvem e aviso/explicação no corpo do e-mail. Metade: só o link na nuvem, sem o que escrever no corpo. Zero: anexar mesmo assim, dividir em vários e-mails sem explicação, usar aplicativo pessoal, ou em branco.'),
      (v_atividade, 5, 1, 'Nome com data AAAA-MM-DD, descrição e versão, com as vantagens explicadas.', 0.5, 'Ex.: "2026-10-16_Relatorio_Estoque_v01.pdf" (data no formato AAAA-MM-DD, descrição do conteúdo e versão). Vantagens: os arquivos ficam em ordem cronológica automática, qualquer pessoa sabe o que é o arquivo sem abri-lo, evita confusão entre versões e retrabalho.', 'Nota cheia: nome com data AAAA-MM-DD, descrição e versão, e pelo menos uma vantagem explicada. Metade: nome adequado sem as vantagens, ou nome sem um dos três elementos com vantagem explicada. Zero: nome genérico ou em branco.'),
      (v_atividade, 6, 1, 'Permissão correta com justificativa e diferença entre Leitor, Comentador e Editor.', 0.5, 'Comentador. Leitor apenas visualiza e baixa; Comentador pode sugerir alterações e deixar notas sem mudar os dados; Editor modifica, exclui e gerencia tudo. Como o supervisor só sugere correções, o Comentador basta e evita alterações por engano.', 'Nota cheia: Comentador, justificativa e a diferença entre as três permissões. Metade: Comentador com justificativa, sem a diferença entre as três (ou com a diferença incompleta). Zero: Leitor, Editor ou em branco.'),
      (v_atividade, 7, 1, 'Conceito de sincronização e significado dos três ícones de status.', 0.5, 'Sincronização é a atualização automática que mantém cópias iguais do arquivo na nuvem e na pasta do computador; o que é salvo offline é enviado quando a conexão volta. Ícones: nuvem = o arquivo está só na nuvem; check verde = disponível no computador (sincronizado); setas circulares = o arquivo está sendo enviado/sincronizando.', 'Nota cheia: conceito de sincronização e os três ícones corretos. Metade: conceito com dois ícones corretos, ou os três ícones sem o conceito. Zero: um ícone ou nenhum correto e sem conceito.'),
      (v_atividade, 8, 1, 'Histórico de versões e restauração de uma versão anterior explicados.', 0.5, 'O histórico de versões. A nuvem guarda as versões anteriores do arquivo; o proprietário abre o histórico, escolhe a versão de antes da exclusão (pela data e horário) e a restaura. Também dá para nomear versões importantes para achá-las mais rápido.', 'Nota cheia: histórico de versões e como restaurar uma versão anterior. Metade: cita o histórico sem explicar como funciona. Zero: digitar de novo, criar outra planilha, pedir ao colega para lembrar, ou em branco.'),
      (v_atividade, 9, 1, 'Uso de @nome ou +e-mail no comentário, notificação e o botão Resolver.', 0.5, 'Selecionar o trecho e inserir um comentário digitando @nome ou +e-mail do colega (ex.: "@João, confira a contagem do corredor B até sexta"). A plataforma notifica o colega e atribui a tarefa a ele. Depois de feita a conferência, clica-se em Resolver para fechar o comentário e manter o documento organizado.', 'Nota cheia: menção com @ ou +, notificação/atribuição e o Resolver. Metade: menção explicada sem o Resolver, ou Resolver sem a menção. Zero: não usa menção (só letras maiúsculas, cor de fonte etc.) ou em branco.'),
      (v_atividade, 10, 1, 'Conceito de comunicação assíncrona e mensagem completa e autoexplicativa.', 0.5, 'Comunicação assíncrona é quando a mensagem não é lida nem respondida na hora, como entre turnos diferentes. Por isso a mensagem precisa ser completa e autoexplicativa. Ex.: "Boa noite, equipe do turno da noite. Ficaram pendentes 3 conferências de recebimento no corredor B (notas 1520, 1521 e 1522). Por favor, conferir e lançar no sistema até as 6h. Qualquer dúvida, deixem um comentário na planilha. Ana – turno da tarde."', 'Nota cheia: conceito correto e mensagem com o pedido, o prazo e o que é preciso, sem depender de resposta. Metade: conceito sem exemplo adequado, ou exemplo adequado sem conceito. Zero: conceito errado e mensagem vaga ("Oi") ou em branco.'),
      (v_atividade, 11, 1, 'Os dois erros explicados e duas boas práticas de netiqueta.', 0.5, 'Escrever em CAPS LOCK equivale a gritar e soa agressivo. "Responder a todos" só para agradecer enche a caixa de entrada de todos com uma mensagem que não interessa ao grupo. Boas práticas: revisar ortografia e concordância antes de enviar, respeitar o horário comercial para mensagens não urgentes, confirmar o recebimento de mensagens importantes em até 24 horas úteis.', 'Nota cheia: os dois erros explicados e duas boas práticas. Metade: os dois erros sem boas práticas, ou um erro e duas boas práticas. Zero: um ou nenhum elemento correto.'),
      (v_atividade, 12, 1, 'Cyberbullying identificado e passos: documentar, não revidar e acionar canais oficiais.', 0.5, 'É cyberbullying (ofensas em chats ou e-mails). Passos: 1) documentar — salvar prints com data, hora e remetente e baixar os registros; 2) não revidar, porque respostas agressivas agravam o conflito e atrapalham a apuração; 3) acionar os canais oficiais (coordenação, RH ou canal de denúncia). A Lei Carolina Dieckmann e o Marco Civil da Internet protegem contra violações digitais.', 'Nota cheia: cyberbullying e os três passos (documentar, não revidar, canais oficiais). Metade: dois dos três passos, ou os três sem nomear a atitude. Zero: revidar, apagar e esquecer, expor nas redes, ou em branco.'),
      (v_atividade, 13, 1, 'Para, CC e Assunto corretos e no padrão.', 0.5, 'Para: coordenacao@almoxarifado.com. CC: compras@almoxarifado.com. Assunto: ex.: "[Almoxarifado] Relatório de levantamento de estoque – Entrega 16/10".', 'Nota cheia: Para e CC nos campos certos e assunto no padrão (setor/projeto, assunto, ação/prazo). Metade: Para e CC certos com assunto vago, ou assunto no padrão com Para e CC trocados. Zero: campos trocados e assunto vago, ou em branco.'),
      (v_atividade, 14, 1, 'Saudação formal, corpo claro com o anexo citado e despedida com assinatura.', 0.5, 'Ex.: "Prezado Coordenador Carlos, envio em anexo o relatório do levantamento de estoque do almoxarifado (PDF), com as quantidades conferidas e as divergências encontradas. Fico à disposição para dúvidas ou ajustes. Atenciosamente, [Nome completo] – Aluno consultor | Turma [número] | [e-mail]."', 'Nota cheia: saudação formal, corpo claro que cita o anexo e despedida com nome e cargo/turma. Metade: falta um desses três elementos, ou usa linguagem informal em uma parte. Zero: sem forma de e-mail formal (gírias, sem saudação nem assinatura) ou em branco.'),
      (v_atividade, 15, 1, 'Estrutura de pastas com as três subpastas e três nomes padronizados.', 0.5, 'Ex.: 2026 / Almoxarifado / Inventario / Rascunhos, Revisao, Final (e outras pastas por assunto, como Pedidos e Recebimento). Novos nomes: "2026-10-16_Planilha_Estoque_v01.xlsx", "2026-10-16_Relatorio_Inventario_v01.pdf", "2026-10-16_Relatorio_Inventario_Final_v02.pdf" (data AAAA-MM-DD, descrição e versão).', 'Nota cheia: estrutura por ano e assunto com Rascunhos, Revisão e Final e três nomes com data AAAA-MM-DD e descrição. Metade: estrutura adequada sem os nomes (ou nomes sem data), ou nomes adequados sem a estrutura. Zero: sem organização ou em branco.'),
      (v_atividade, 16, 1, 'Permissão correta do auxiliar e do supervisor, com justificativa.', 0.5, 'Auxiliar: Editor, porque precisa lançar entradas e saídas todos os dias (alterar os dados). Supervisor: Comentador, porque só revisa e sugere correções, sem mudar os dados.', 'Nota cheia: Editor para o auxiliar e Comentador para o supervisor, com justificativa. Metade: as duas permissões certas sem justificativa, ou uma certa com justificativa. Zero: as duas erradas ou em branco.'),
      (v_atividade, 17, 1, 'Permissão correta do estagiário e do fornecedor, com justificativa.', 0.5, 'Estagiário: Leitor, porque só consulta o saldo e não precisa alterar nem comentar. Fornecedor externo: Comentador, porque vai opinar sobre a lista sem poder alterar os dados (nunca Editor, por ser pessoa de fora; também não com link público).', 'Nota cheia: Leitor para o estagiário e Comentador para o fornecedor, com justificativa. Metade: as duas certas sem justificativa, ou uma certa com justificativa. Aceitar Leitor para o fornecedor se a justificativa for coerente com segurança. Zero: Editor para o fornecedor ou as duas erradas.'),
      (v_atividade, 18, 1, 'Os quatro passos na ordem correta.', 0.5, '1) Criar a pasta com nome padronizado no diretório correto; 2) inserir os arquivos técnicos finais nos formatos adequados (ex.: PDF); 3) configurar o nível de permissão (Leitor ou Editor) para os e-mails da equipe; 4) enviar o link seguro com um e-mail formal explicando o objetivo.', 'Nota cheia: os quatro passos na ordem correta. Metade: os quatro passos com dois fora de ordem, ou três passos na ordem certa. Zero: dois passos ou menos, ou ordem sem lógica (ex.: enviar o link antes de criar a pasta).'),
      (v_atividade, 19, 1, 'Riscos de vazamento, perda ou alteração de arquivos e violação de normas e privacidade.', 0.5, 'Com link público de Editor, qualquer pessoa que tiver o link (inclusive desconhecidos na lan house) pode ver, copiar, alterar ou apagar os arquivos: há risco de vazamento de dados, perda ou sabotagem dos documentos, descumprimento das normas da empresa e violação de privacidade (LGPD). Computadores públicos ainda podem guardar a sessão aberta.', 'Nota cheia: pelo menos dois riscos explicados (vazamento, perda/alteração, normas/privacidade). Metade: um risco explicado. Zero: diz que não há risco ou em branco.'),
      (v_atividade, 20, 1, 'Restringir o acesso, auditar o histórico e orientar o colega com empatia e firmeza.', 0.5, 'Restringir o acesso na hora: tirar o link público e deixar só os e-mails da equipe com a permissão adequada; auditar o histórico de versões e de atividade para ver se algo foi alterado ou apagado e restaurar se preciso; sair da conta no computador público. Conversar com o colega com empatia e firmeza: explicar os riscos sem culpá-lo nem expô-lo, mostrar o jeito seguro de trabalhar fora (acesso pessoal com login) e combinar que não se repita.', 'Nota cheia: restringir o acesso, auditar/restaurar pelo histórico e orientação com empatia e firmeza. Metade: dois desses três. Zero: um ou nenhum, ou orientação agressiva/punitiva sem medida técnica.');
end $$;
